"""The CI lock check flags a lock that its recorded uv command would change."""

from __future__ import annotations

import importlib.util
from collections.abc import Callable, Sequence
from pathlib import Path

import pytest

_SPEC = importlib.util.spec_from_file_location(
    "check_requirement_locks", Path("scripts/check_requirement_locks.py")
)
assert _SPEC is not None and _SPEC.loader is not None
check = importlib.util.module_from_spec(_SPEC)
_SPEC.loader.exec_module(check)

_HEADER = (
    "# This file was autogenerated by uv via the following command:\n"
    "#    uv pip compile --universal --python-version 3.12 --generate-hashes "
    "dev.in --output-file dev.txt\n"
)


def _lock_dir(tmp_path: Path, body: str) -> Path:
    directory = tmp_path / "requirements"
    directory.mkdir()
    (directory / "dev.in").write_text("click\n", encoding="utf-8")
    (directory / "dev.txt").write_text(_HEADER + body, encoding="utf-8")
    return directory


def _uv_writes(body: str) -> Callable[[Sequence[str], Path], None]:
    def run(command: Sequence[str], cwd: Path) -> None:
        assert list(command[:3]) == ["uv", "pip", "compile"]
        assert "--universal" in command
        (cwd / "dev.txt").write_text(_HEADER + body, encoding="utf-8")

    return run


def test_a_lock_matching_uv_passes(tmp_path: Path) -> None:
    body = "colorama==0.4.6 ; sys_platform == 'win32'\n"
    assert check.stale_locks(_lock_dir(tmp_path, body), _uv_writes(body)) == []


def test_a_lock_missing_platform_markers_is_reported(tmp_path: Path) -> None:
    committed = "uvloop==0.23.0\n"
    universal = "uvloop==0.23.0 ; sys_platform != 'win32'\n"
    problems = check.stale_locks(_lock_dir(tmp_path, committed), _uv_writes(universal))
    assert len(problems) == 1
    assert "sys_platform != 'win32'" in problems[0]


def test_a_lock_without_a_recorded_command_is_an_error(tmp_path: Path) -> None:
    directory = tmp_path / "requirements"
    directory.mkdir()
    (directory / "dev.txt").write_text("click==8.0\n", encoding="utf-8")
    with pytest.raises(ValueError, match="no recorded"):
        check.stale_locks(directory, _uv_writes(""))
